package local.snapexplorer.mobile;
import android.app.*;import android.content.*;import android.database.*;import android.graphics.Typeface;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
/** Local browser for every retained JSON dataset, including unknown formats. */
public final class MetadataActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler ui=new Handler(Looper.getMainLooper());private ChatRepository repo;private AppStyle style;private LinearLayout root,content;private TextView subtitle;private boolean dead,busy;private int generation;private String selectedId,selectedName,pendingId;private long offset;private final List<Long> history=new ArrayList<>();
 @Override public void onCreate(Bundle state){AppStyle.apply(this);super.onCreate(state);AppStyle.systemBars(this);style=new AppStyle(this);repo=new ChatRepository(this);if(state!=null)pendingId=state.getString("pending_id");if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(0,this::back);String id=getIntent().getStringExtra("dataset_id");if(state!=null)id=state.getString("dataset_id",id);if(id!=null){selectedId=id;selectedName=getIntent().getStringExtra("filename");if(state!=null)selectedName=state.getString("filename",selectedName);page(0);}else catalog();}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private TextView text(String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);return t;}
 private Button button(String name,Runnable action){Button b=new Button(this);b.setText(name);b.setTextSize(13);b.setAllCaps(false);b.setTextColor(style.ink);b.setOnClickListener(v->action.run());return b;}
 private void post(int token,Runnable action){ui.post(()->{if(!dead&&token==generation)action.run();});}
 private void shell(String title,String detail){generation++;root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(style.background);root.setOnApplyWindowInsetsListener((v,in)->{v.setPadding(dp(12),in.getSystemWindowInsetTop()+dp(8),dp(12),in.getSystemWindowInsetBottom()+dp(8));return in;});setContentView(root);LinearLayout heading=new LinearLayout(this);heading.setGravity(Gravity.CENTER_VERTICAL);heading.addView(button("‹",this::back),new LinearLayout.LayoutParams(dp(48),dp(48)));LinearLayout names=new LinearLayout(this);names.setOrientation(1);names.setPadding(dp(8),0,0,dp(8));TextView h=text(title==null?"JSON data":title,20,style.ink);h.setTypeface(null,Typeface.BOLD);h.setMaxLines(2);names.addView(h);subtitle=text(detail,12,style.muted);names.addView(subtitle);heading.addView(names,new LinearLayout.LayoutParams(0,-2,1));if(selectedId==null){Button refresh=button("↻",()->{worker.execute(()->{repo.getWritableDatabase().delete("settings","key=?",new String[]{"export_catalog"});ui.post(()->{if(!dead)catalog();});});});refresh.setContentDescription("Refresh dataset index");heading.addView(refresh,new LinearLayout.LayoutParams(dp(48),dp(48)));}root.addView(heading);content=new LinearLayout(this);content.setOrientation(1);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));root.requestApplyInsets();}
 private void catalog(){selectedId=null;selectedName=null;history.clear();shell("Export data","Indexing all imported JSON locally…");int token=generation;content.addView(new ProgressBar(this));worker.execute(()->{try{ExportCatalog.ensure(repo,(done,total)->post(token,()->subtitle.setText("Indexing dataset "+done+" of "+total)));List<String[]> rows=new ArrayList<>();try(Cursor c=repo.getReadableDatabase().rawQuery("SELECT m.id,m.filename,COALESCE(d.category,'Other data'),COALESCE(d.records,0),COALESCE(d.refs,0),COALESCE(d.matched,0),COALESCE(d.issue,'') FROM metadata m LEFT JOIN dataset_catalog d ON d.metadata_id=m.id ORDER BY d.category,m.filename",null)){while(c.moveToNext())rows.add(new String[]{c.getString(0),c.getString(1),c.getString(2),c.getString(3),c.getString(4),c.getString(5),c.getString(6)});}post(token,()->{content.removeAllViews();subtitle.setText(rows.size()+" datasets · all retained on this phone");EditText filter=new EditText(this);filter.setSingleLine(true);filter.setHint("Filter datasets");filter.setTextColor(style.ink);filter.setHintTextColor(style.muted);content.addView(filter);ListView list=new ListView(this);List<String[]> shown=new ArrayList<>(rows);BaseAdapter adapter=new BaseAdapter(){public int getCount(){return shown.size();}public Object getItem(int p){return shown.get(p);}public long getItemId(int p){return p;}public View getView(int p,View old,ViewGroup parent){String[] r=shown.get(p);LinearLayout cell=new LinearLayout(MetadataActivity.this);cell.setOrientation(1);cell.setPadding(dp(8),dp(12),dp(8),dp(12));TextView name=text(r[1],15,style.ink);name.setTypeface(null,Typeface.BOLD);cell.addView(name);cell.addView(text(r[2]+" · "+r[3]+" observed records",12,style.muted));if(!r[4].equals("0"))cell.addView(text(r[5]+" of "+r[4]+" local references matched",12,style.accent));if(!r[6].isEmpty())cell.addView(text("Partial index · full JSON retained",12,style.muted));cell.setOnClickListener(v->{selectedId=r[0];selectedName=r[1];history.clear();page(0);});return cell;}};list.setAdapter(adapter);list.setOnItemClickListener((p,v,n,id)->{String[] r=shown.get(n);selectedId=r[0];selectedName=r[1];history.clear();page(0);});content.addView(list,new LinearLayout.LayoutParams(-1,0,1));filter.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void afterTextChanged(android.text.Editable s){}public void onTextChanged(CharSequence s,int start,int before,int count){String q=s.toString().toLowerCase(Locale.ROOT);shown.clear();for(String[] r:rows)if((r[1]+" "+r[2]).toLowerCase(Locale.ROOT).contains(q))shown.add(r);adapter.notifyDataSetChanged();}});if(rows.isEmpty())content.addView(text("No JSON datasets have been imported yet.",16,style.muted));});}catch(Exception failure){post(token,()->{content.removeAllViews();content.addView(text("Could not index all datasets. Your original data is unchanged.",16,style.muted));content.addView(button("Retry",this::catalog));});}});}
 private void page(long at){if(busy)return;busy=true;offset=at;shell(selectedName,"Reading locally…");int token=generation;content.addView(new ProgressBar(this));String id=selectedId;worker.execute(()->{try{String stored=stored(id);MetadataTextPage result;try(Reader reader=MetadataStore.reader(repo.getReadableDatabase(),stored)){result=MetadataTextPage.read(reader,at,24000);}post(token,()->{busy=false;content.removeAllViews();subtitle.setText("JSON characters "+(result.text.isEmpty()?at:at+1)+"–"+result.next+(result.ended?" · end":" · continued"));ScrollView scroll=new ScrollView(this);TextView body=text(result.text,13,style.ink);body.setTypeface(Typeface.MONOSPACE);body.setTextIsSelectable(true);body.setPadding(dp(6),dp(10),dp(6),dp(10));scroll.addView(body);content.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout actions=new LinearLayout(this);Button previous=button("Previous",()->{if(!history.isEmpty())page(history.remove(history.size()-1));});previous.setEnabled(!history.isEmpty());actions.addView(previous,new LinearLayout.LayoutParams(0,dp(48),1));Button next=button("Next",()->{history.add(at);page(result.next);});next.setEnabled(!result.ended);actions.addView(next,new LinearLayout.LayoutParams(0,dp(48),1));actions.addView(button("Save full JSON",()->save(id)),new LinearLayout.LayoutParams(0,dp(48),1));content.addView(actions);});}catch(Exception failure){post(token,()->{busy=false;content.removeAllViews();content.addView(text("This retained dataset is missing or failed its integrity check. Original source ZIPs are unchanged.",16,style.muted));});}});}
 private String stored(String id)throws IOException{try(Cursor c=repo.getReadableDatabase().rawQuery("SELECT json FROM metadata WHERE id=?",new String[]{id})){if(c.moveToFirst())return c.getString(0);}throw new IOException("Dataset not found");}
 private void save(String id){pendingId=id;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("application/json");intent.putExtra(Intent.EXTRA_LOCAL_ONLY,true);intent.putExtra(Intent.EXTRA_TITLE,MediaNames.safeFileName(selectedName==null?"export-data.json":selectedName.substring(selectedName.lastIndexOf('/')+1)));startActivityForResult(intent,91);}
 @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(request!=91)return;String id=pendingId;pendingId=null;if(result!=RESULT_OK||id==null||intent==null||intent.getData()==null)return;Uri target=intent.getData();worker.execute(()->{try{String value=stored(id);File file=MetadataStore.file(repo.getReadableDatabase(),value);try(InputStream in=file==null?new ByteArrayInputStream(value.getBytes(StandardCharsets.UTF_8)):new FileInputStream(file);OutputStream out=getContentResolver().openOutputStream(target,"wt")){if(out==null)throw new IOException("Destination unavailable");byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted())throw new IOException("Save interrupted");out.write(buffer,0,n);}}ui.post(()->{if(!dead)Toast.makeText(this,"Full dataset saved",Toast.LENGTH_SHORT).show();});}catch(Exception failure){ui.post(()->{if(!dead)new AlertDialog.Builder(this).setTitle("Save did not finish").setMessage("Your imported data is unchanged. The chosen destination may contain an incomplete file.").setPositiveButton("OK",null).show();});}});}
 private void back(){if(selectedId!=null){busy=false;catalog();}else finish();}
 @Override public void onBackPressed(){back();}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("pending_id",pendingId);out.putString("dataset_id",selectedId);out.putString("filename",selectedName);}
 @Override protected void onDestroy(){dead=true;generation++;worker.shutdownNow();new Thread(()->{try{worker.awaitTermination(30,TimeUnit.SECONDS);}catch(InterruptedException ignored){}if(worker.isTerminated())repo.close();},"close-dataset-browser").start();super.onDestroy();}
}
